from common import *
from html import escape

def main():
 cases=read(E/'results/cases.json');ex=read(E/'results/extraction.json');proj=read(E/'results/projection.json')
 items=[]
 for r in cases:
  fn='case_D_refused.png'if r['case_id']=='D'else f'case_{r["case_id"]}.png'
  rows=[('执行动作',r['skill']+'；参数 '+json.dumps(r['actual_executor_arguments'],ensure_ascii=False)),('当前真实状态',r['current_semantics']),('实际发生',r['actual_event']),('预测后继命题',r['predicted_semantics']),('真实后继命题',r['actual_semantics']),('一致与错误',r['agreement']+' '+r['mismatch']),('原256维误差',f'{r["latent_mse_AB_standardized"]:.4f}，AB标准化MSE'),('错误归因边界',r['diagnostic'])]
  table=''.join('<tr><th>'+escape(k)+'</th><td>'+escape(v)+'</td></tr>'for k,v in rows)
  provenance={k:r[k]for k in['case_id','id','root_id','condition','status','skill','action','before_state_id','after_state_id','before_frame','after_frame','before_path','after_path','before_sha256','after_sha256','actual_controls','native_reason','candidate_pair_ids']}
  items.append(f'<article id="case-{r["case_id"]}"><h2>案例 {r["case_id"]} · {escape(r["title"])}</h2><a href="{fn}"><img class="figure" src="{fn}" alt="{escape(r["title"])}：当前、预测和真实后继共同投影"></a><table>{table}</table><p><b>语义读出的限制：</b>{escape(r["diagnostic"])}</p><details><summary>查看真实前后双相机原图</summary><div class="photos"><img src="images/{r["case_id"]}_before.jpg" alt="真实执行前固定与腕部相机"><img src="images/{r["case_id"]}_after.jpg" alt="真实执行后固定与腕部相机"></div></details><details><summary>查看动作、root、状态、帧与来源</summary><pre>{escape(json.dumps(provenance,ensure_ascii=False,indent=2))}</pre></details></article>')
 css='body{font:16px/1.75 system-ui,"Noto Sans CJK SC",sans-serif;color:#243747;background:#f4f6f8;margin:0}main{max-width:1280px;margin:auto;padding:24px}h1{font-size:28px;line-height:1.4}h2{font-size:23px}article,section{background:white;border:1px solid #dce4ea;border-radius:12px;padding:22px;margin:20px 0}.figure{width:100%;height:auto}table{border-collapse:collapse;width:100%;font-size:15px}th,td{text-align:left;vertical-align:top;padding:9px;border-bottom:1px solid #dce4ea}th{width:170px;background:#f0f4f7}a{color:#176eaa}.note{border-left:4px solid #cc963c;padding-left:14px}.photos{display:flex;gap:12px;flex-wrap:wrap}.photos img{max-width:48%;height:auto}pre{overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}nav{display:flex;gap:24px;flex-wrap:wrap}summary{cursor:pointer}code{overflow-wrap:anywhere}@media(max-width:700px){main{padding:10px}section,article{padding:12px}th{width:100px}.photos img{max-width:100%}}'
 intro='四个封存案例使用同一个匹配臂模型 canonical_matched、seed 0、update1000。背景与四例的当前/预测/真实后继在一次共同拟合中得到坐标；所有面板共享轴与范围。没有新增训练、仿真、模型选择或测试分数。'
 method='''<section><h2>图中每个元素的含义</h2><p>蓝圆是当前真实观测编码；橙三角是给定实际技能动作的一步预测向量；绿星是真实执行后观测的编码。橙色虚线箭头从当前指向预测，绿色实线箭头从当前指向真实。淡灰是此前固定的338个真实技能边界背景状态。彩色细引线只帮助标注邻近点，所有点都没有移位或加抖动。</p><p>一个点是一个256维连续隐状态向量的二维位置。这里的“分布”指有限样本点云，<b>不是概率密度，也不是同一动作的多个随机预测</b>。每例只有一个当前、一个预测、一个真实后继。每张图右侧均为真实前后RGB；预测模型没有生成图像。</p><p>案例A–D只是四例编号，均来自已用测试批次D2（物理环境D）；灰色背景包括真实A/B/C/D场景。D2不是额外环境域。t-SNE轴无物理单位，簇大小、整体间距和箭头长度不能直接作为预测准确性。</p></section>
<section><h2>选例与统一投影</h2><p>在读取这些案例的模型预测与误差前固定规则：依次取开抽屉/蓝/reference/success、抓取/粉/reference/success、正常放置/红/held_open/success、关闭抽屉放置/蓝/held_closed/refused。每组按(root_id,pair_id)字典序取第一个未使用root。固定颜色用于覆盖不同物块，未按结果好看程度选例。成功/拒绝仅用于用户要求的案例类别，不是模型质量筛选。</p><p>338背景+12案例角色=350个逻辑点。7个真实端点已在背景中，使用同一状态身份与坐标，不重复加权；最终343个独立向量共同拟合一次。当前与真实重合或接近时使用引线，不移动坐标。旧主图坐标没有直接套用，新图不能与旧图比较轴距离。</p><p>标准化沿用此前102个AB训练点的256维均值/标准差，标准差下限1e-6。PCA50 full SVD在343个无标签向量上拟合；随后t-SNE：random_state42、perplexity30、PCA初始化、learning_rate=auto（实际50）、early_exaggeration12、max_iter1500、Barnes–Hut angle0.5、欧氏距离、n_jobs1。只拟合一次，无按视觉效果重试。</p><p>原空间误差：<code>mean_j[((预测_j − 真实_j) / AB标准差_j)^2]</code>，j=1…256，无物理单位；它在完整256维表示计算，不是PCA/t-SNE距离。它度量连续表示偏差，不是语义准确率，也不具备跨模型的绝对标尺。</p></section>
<section><h2>来源和限制</h2><p>编码器的全部非转移参数逐张量确认与前次主图模型一致。四个预测向量直接读取此前D2预测文件，动作向量与真实执行记录逐项核对。真实RGB使用原始boundary NPZ，标题中的frame是对应分支连续录像里的记录帧索引。抓取动作带目标颜色；place_in_drawer表示放下当前持物，不额外传入目标颜色；8维动作末位1对应原有96帧稳定等待配置。</p><p>命题来自冻结查询头：持物/入屉使用既有0.5阈值，抽屉三类取最大概率。真值只用于文字、用户要求的结果分层及诊断，不进入标准化、PCA或t-SNE。案例D中该查询头对真实后继也误判抽屉打开，因此不能仅凭预测命题错误认定动力学模型是唯一原因。未进行额外修正或重新评估。</p><p class="note">这些是已用测试数据的说明性案例，不是新的独立泛化测试，也不是整体性能估计。没有宣称原完整预实验方案完成。当前浏览器工具此前拒绝file:地址，本次未重试或绕过；报告通过静态资源与数值映射检查，不声称浏览器交互测试成功。</p><p><a href="README.md">完整README</a> · 本地报告内所有资源均可离线打开。</p></section>'''
 html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>动作后的真实与预测：四案例对照</title><style>'+css+'</style><main><h1>当前状态 + 动作 → 预测后继 / 真实后继</h1><p>'+intro+'</p><nav>'+''.join(f'<a href="#case-{r["case_id"]}">案例{r["case_id"]} · {escape(r["title"])}</a>'for r in cases)+'</nav><section><a href="action_cases_overview.png"><img class="figure" src="action_cases_overview.png" alt="四案例总览"></a></section>'+''.join(items)+method+'<details><summary>固定模型哈希和实际投影记录</summary><pre>'+escape(json.dumps({'model':ex['model'],'projection':proj},ensure_ascii=False,indent=2))+'</pre></details></main></html>'
 (R/'index.html').write_text(html)
 md=['# 当前状态、实际动作、预测与真实后继：四个封存案例','',intro,'','入口：[本地HTML](index.html)、[四案例总览](action_cases_overview.png)、[拒绝案例高清图](case_D_refused.png)。','',
 '| 案例 | 动作 / pair | root | 帧 | 原256维AB标准化MSE | 预测与真实的差异 |','|---|---|---|---|---:|---|']
 for r in cases:md.append(f'| {r["case_id"]} | {r["skill"]} / {r["id"]} | {r["root_id"]} | {r["before_frame"]}→{r["after_frame"]} | {r["latent_mse_AB_standardized"]:.4f} | {r["mismatch"]} |')
 md+=['','## 读图', '', '蓝圆：当前；橙三角：一步预测；绿星：真实后继。虚线/实线箭头分别连接当前到预测/真实，浅灰为338个真实背景状态。细引线只用于标注，坐标未移位。轴无物理单位，所有小面板共享同一轴范围。点云不是概率密度，每例只含一个预测向量。右侧均为真实执行前后的固定/腕部相机；没有预测RGB。', '', '案例A–D只是编号，均为D2已用测试（物理环境D）；背景包括物理A/B/C/D。不能将案例编号解释为场景域。', '', '## 选例及动作身份', '',read(E/'configs/protocol.json')['selection'], '', '只用指定结果类别分层；不按误差、语义正确率或二维位置选择。四例root互不相同。拒绝例没有执行place底层控制（0步），仍记录96帧稳定等待；不能称为机械动作执行后失败。', '', '动作是原记录的8维向量：[open,lift,place,close,red,blue,pink,hold/96]。只有lift带颜色；place不绑定额外颜色。完整数组、执行器参数、候选序列、NPZ路径/哈希、state和frame ID见实验目录 data/cases.json、results/cases.json。', '', '## 同一个模型和同一次投影', '', f'模型：`{ex["model"]["path"]}`',f'SHA256：`{ex["model"]["sha256"]}`', '', '全部非转移参数逐张量与原主图交互编码器一致。冻结连续表示为4×64展平256维；预测来自封存 D2_canonical_matched_seed0.npz。既有查询头阈值不变。真实端点批量编码与背景缓存的最大浮点偏差≤1.2e-6，复用同一身份的背景向量以避免重复。', '', '350个逻辑点（338+4×3）中7个是真实端点重复角色，合并为343个共同拟合点；完整映射在 results/coordinates.npz。未沿用旧t-SNE坐标，未分别拟合案例。', '', '标准化沿用102个入选AB训练点的均值/标准差（下限1e-6）；PCA50 full SVD对343无标签向量拟合。t-SNE：seed42、perplexity30、init=pca、learning_rate=auto（50）、early_exaggeration12、max_iter1500、Barnes–Hut angle0.5、euclidean、n_jobs1；scikit-learn1.7.2。实际n_iter_=1499，PCA保留方差97.5645%。仅一次拟合，不择优重试。', '', '所有图轴范围：x=[-36.0807724,26.2747688]，y=[-37.3986206,21.5611897]。标签不进入拟合；D2仅诊断，不修改模型选择、阈值或测试分数。', '', '## 原空间误差的尺度', '', '`MSE = mean_j[((z_pred[j]-z_actual[j])/AB_std[j])²]`，j=1…256。这是按训练集标准差归一后的完整连续表示均方差，无物理单位；不是二维线长、分类误差或概率。各例共用模型和尺度。原始未标准化MSE也存入结果用于与封存记录数值核对，不增加用户图表指标。', '', '## 有限结论与错误来源', '']
 for r in cases:md+=['- 案例'+r['case_id']+'：'+r['actual_event']+' '+r['agreement']+' '+r['mismatch']+' '+r['diagnostic']]
 md+=['','图上很近仍可能读错命题。尤其D例，真实后继编码的同一查询头也判“打开”，不能把错误全部归因于转移模型。未进行进一步修补或新测试。','', '## 交付与验证', '', '5张PNG（总览+4单例）、8张原始双相机拼图、HTML/README。封存配置、模型哈希、来源、数组、脚本和验证记录位于独立 experiments/latent_action_cases_20261016；旧latent_tsne报告不变。浏览器此前的file:策略拒绝仍有效，本次不重试或绕过。只做静态资源、原始数据映射、数值和哈希验证，不声称浏览器交互实测。','', 'Library仅请求保存总览和D拒绝案例PNG，其余留本机。上传结果另存实验目录results；失败不阻塞本地交付。','', '只读验证：`source /home/robot/research/projects/wm_symbolic/env.sh` 后运行 `python /home/robot/research/projects/wm_symbolic/experiments/latent_action_cases_20261016/source/verify.py`。']
 (R/'README.md').write_text('\n'.join(md)+'\n');print('HTML_README_READY',flush=True)
if __name__=='__main__':main()
